draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw chair
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 50);
  ctx.lineTo(W/2 + 50, H/2 - 50);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 - 50, H/2 + 50);
  ctx.closePath();
  ctx.stroke();

  // draw grief (a faint stick figure)
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 70 + 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60 + 20 * Math.sin(t));
  ctx.lineTo(W/2, H/2 - 40 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 45 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 20 + 10 * Math.cos(t), H/2 - 25 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 45 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(t), H/2 - 25 + 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
